    def getArgList(self):
        return self.args

    def getArgs(self):
        return list(self.args)

    def getOptions(self):
        return list(self.options)

    def _resolveOption(self, opt):
        actual = Util.stripLeadingHyphens(opt)
        if actual is not None:
            for option in self.options:
                if actual == option.getOpt() or actual == option.getLongOpt():
                    return option
        return None

    def _handleDeprecated(self, option):
        if self.deprecatedHandler is not None:
            self.deprecatedHandler(option)

    def hasOption(self, opt):
        if isinstance(opt, Option):
            result = opt in self.options
            if result and opt.isDeprecated():
                self._handleDeprecated(opt)
            return result
        elif isinstance(opt, OptionGroup):
            if opt is None or not opt.isSelected():
                return False
            return self.hasOption(opt.getSelected())
        else:
            resolved = self._resolveOption(str(opt))
            return self.hasOption(resolved) if resolved is not None else False

    def getOptionValues(self, opt):
        if isinstance(opt, Option):
            if opt is None:
                return None
            values = []
            for processedOption in self.options:
                if processedOption == opt:
                    if opt.isDeprecated():
                        self._handleDeprecated(opt)
                    values.extend(processedOption.getValuesList())
            return values if values else None
        elif isinstance(opt, OptionGroup):
            if opt is None or not opt.isSelected():
                return None
            return self.getOptionValues(opt.getSelected())
        else:
            resolved = self._resolveOption(str(opt))
            return self.getOptionValues(resolved) if resolved is not None else None

    def getOptionValue(self, opt, defaultValue=None):
        if isinstance(opt, Option):
            values = self.getOptionValues(opt)
            answer = values[0] if values else None
            if answer is not None:
                return answer
            return defaultValue() if callable(defaultValue) else defaultValue
        elif isinstance(opt, OptionGroup):
            values = self.getOptionValues(opt)
            answer = values[0] if values else None
            if answer is not None:
                return answer
            return defaultValue() if callable(defaultValue) else defaultValue
        else:
            resolved = self._resolveOption(str(opt))
            return self.getOptionValue(resolved, defaultValue)

    def getParsedOptionValue(self, opt, defaultValue=None):
        if isinstance(opt, Option):
            if opt is None:
                return defaultValue() if callable(defaultValue) else defaultValue
            res = self.getOptionValue(opt)
            try:
                if res is None:
                    return defaultValue() if callable(defaultValue) else defaultValue
                converter = opt.getConverter()
                return converter(res)
            except Exception as e:
                raise ParseException.wrap(e)
        elif isinstance(opt, OptionGroup):
            if opt is None or not opt.isSelected():
                return defaultValue() if callable(defaultValue) else defaultValue
            return self.getParsedOptionValue(opt.getSelected(), defaultValue)
        else:
            resolved = self._resolveOption(str(opt))
            return self.getParsedOptionValue(resolved, defaultValue)

    def getOptionProperties(self, opt):
        props = {}
        if isinstance(opt, Option):
            for processedOption in self.options:
                if processedOption == opt:
                    self._processPropertiesFromValues(props, processedOption.getValuesList())
        else:
            opt_str = str(opt)
            for option in self.options:
                if opt_str == option.getOpt() or opt_str == option.getLongOpt():
                    self._processPropertiesFromValues(props, option.getValuesList())
        return props

    def _processPropertiesFromValues(self, props, values):
        i = 0
        while i < len(values):
            if i + 1 < len(values):
                props[values[i]] = values[i + 1]
            else:
                props[values[i]] = "true"
            i += 2

